begin;set local role postgres;create extension if not exists pgtap with schema extensions;set local search_path=public,extensions,pgtap;select plan(64);
select ok(to_regclass(format('public.%I',table_name)) is not null,format('tabela %s existe',table_name)) from unnest(array['erp_financial_categories','erp_cost_centers','erp_financial_accounts','erp_financial_entries','erp_installments','erp_settlements','erp_settlement_allocations','erp_financial_movements','erp_bank_accounts','erp_bank_transactions','erp_bank_reconciliations','erp_bank_reconciliation_items','erp_card_receivables','erp_checks','erp_billing_slips']) names(table_name);
select ok(c.relrowsecurity,format('RLS ativo em %s',c.relname)) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname=any(array['erp_financial_categories','erp_cost_centers','erp_financial_accounts','erp_financial_entries','erp_installments','erp_settlements','erp_settlement_allocations','erp_financial_movements','erp_bank_accounts','erp_bank_transactions','erp_bank_reconciliations','erp_bank_reconciliation_items','erp_card_receivables','erp_checks','erp_billing_slips']) order by c.relname;
select ok(not has_table_privilege('anon',format('public.%I',table_name),'SELECT'),format('anon não lê %s',table_name)) from unnest(array['erp_financial_entries','erp_settlements','erp_financial_movements','erp_bank_transactions']) names(table_name);
select ok(has_table_privilege('authenticated',format('public.%I',table_name),'SELECT'),format('authenticated lê %s sob RLS',table_name)) from unnest(array['erp_financial_entries','erp_settlements','erp_financial_movements','erp_bank_transactions']) names(table_name);
select ok(not has_table_privilege('authenticated',format('public.%I',table_name),'DELETE'),format('authenticated não exclui %s',table_name)) from unnest(array['erp_financial_entries','erp_settlements','erp_financial_movements','erp_bank_transactions']) names(table_name);
select ok(not has_table_privilege('authenticated',format('public.%I',table_name),'UPDATE'),format('livro imutável %s',table_name)) from unnest(array['erp_financial_entries','erp_installments','erp_settlements','erp_settlement_allocations','erp_financial_movements','erp_bank_transactions']) names(table_name);
select ok(not has_table_privilege('authenticated',format('public.%I',table_name),'INSERT'),format('escrita somente por RPC em %s',table_name)) from unnest(array['erp_financial_entries','erp_installments','erp_financial_movements']) names(table_name);
select is((select count(*)::integer from public.erp_permissions where key in('finance.read','finance.entry','finance.settle','finance.reverse','finance.adjust','treasury.read','treasury.manage','treasury.transfer','banking.read','banking.import','banking.reconcile','receivables.read','receivables.manage','payables.read','payables.manage')),15,'quinze permissões M08 existem');
select ok(not has_function_privilege('anon','public.erp_post_financial_entry(uuid,uuid,uuid,text,text,numeric,date,date[],text)','EXECUTE'),'anon não posta título');select ok(has_function_privilege('authenticated','public.erp_post_financial_entry(uuid,uuid,uuid,text,text,numeric,date,date[],text)','EXECUTE'),'authenticated posta título por RPC');
select ok(not has_function_privilege('anon','public.erp_confirm_settlement(uuid,uuid,text)','EXECUTE'),'anon não liquida');select ok(has_function_privilege('authenticated','public.erp_confirm_settlement(uuid,uuid,text)','EXECUTE'),'authenticated liquida por RPC');
select ok(not has_function_privilege('anon','public.erp_transfer_financial_balance(uuid,uuid,uuid,numeric,text)','EXECUTE'),'anon não transfere');select ok(has_function_privilege('authenticated','public.erp_transfer_financial_balance(uuid,uuid,uuid,numeric,text)','EXECUTE'),'authenticated transfere por RPC');
select ok(exists(select 1 from pg_constraint where conname='erp_financial_entries_tenant_id_idempotency_key_key'),'título idempotente');select ok(exists(select 1 from pg_constraint where conname='erp_settlements_tenant_id_idempotency_key_key'),'liquidação idempotente');select ok(exists(select 1 from pg_constraint where conname='erp_financial_movements_tenant_id_idempotency_key_key'),'movimento idempotente');select ok(exists(select 1 from pg_constraint where conname='erp_bank_reconciliations_tenant_id_idempotency_key_key'),'conciliação idempotente');
select ok(exists(select 1 from pg_constraint where conname='erp_settlements_check'),'líquido reconciliado');select ok(exists(select 1 from pg_constraint where conname='erp_settlement_allocations_check'),'alocação reconciliada');
select * from finish();rollback;
